CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,filename TEXT NOT NULL,stored_name TEXT NOT NULL UNIQUE,mime_type TEXT NOT NULL,kind TEXT NOT NULL,size_bytes INTEGER NOT NULL,title TEXT NOT NULL DEFAULT '',alt_text TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS banners(id TEXT PRIMARY KEY,media_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,title TEXT NOT NULL DEFAULT '',subtitle TEXT NOT NULL DEFAULT '',cta_label TEXT NOT NULL DEFAULT '',target_url TEXT NOT NULL DEFAULT '',placement TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,start_at TEXT,end_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_banners_public ON banners(placement,active,sort_order);
